steps.run:
platform=${{ matrix.platform }}
echo "PLATFORM_PAIR=${platform//\//-}" >> $GITHUB_ENV
# Transform multi-line variable into comma-separated variable
image_names=${PUSH_TO_IMAGES//$'\n'/,}
image_names_split=${image_names%,}
echo "IMAGE_NAMES=${image_names_split,,}" >> $GITHUB_ENV

with.build-args:
MASTODON_VERSION_PRERELEASE=${{ inputs.version_prerelease }}
MASTODON_VERSION_METADATA=${{ inputs.version_metadata }}
SOURCE_COMMIT=${{ github.sha }}

with.restore-keys:
assets-${{ github.head_ref || github.ref_name }}-${{ github.sha }}
assets-${{ github.head_ref || github.ref_name }}
assets-main
assets

rspec-persistence-${{ github.head_ref || github.ref_name }}-${{ github.sha }}
rspec-persistence-${{ github.head_ref || github.ref_name }}
rspec-persistence-main
rspec-persistence
